# Since I can't import the library directly, I'll manually analyze
# the patterns by looking at what changes in each pair

inputs = ['ay', 'ab', 'ygj', 'ejkbc', 'yeui']
outputs = ['axvf', 'ab', 'xvfjdj', 'ejkbaeae', 'xvfeui']

# Let me manually identify the differences:
print("Analyzing transformations:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    if inp != outp:
        print(f"{inp} -> {outp}")
        # Find what changed
        if len(inp) == len(outp):
            # Same length - character substitution
            for j, (char_in, char_out) in enumerate(zip(inp, outp)):
                if char_in != char_out:
                    print(f"  Position {j}: '{char_in}' -> '{char_out}'")
        else:
            # Different lengths - substring replacement
            print(f"  Length change: {len(inp)} -> {len(outp)}")
    else:
        print(f"{inp} -> {outp} (no change)")

